
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_rmggac_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_rmggac", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.650654727117409e-02, -2.645928861594773e-02, -2.638926156152058e-02, -2.628416683429649e-02, -2.612361908786751e-02, -2.587250341583801e-02, -2.546916324805657e-02, -2.481827387880088e-02, -2.395515489102355e-02, -2.448626226723626e-02, -2.788632489219783e-02, -4.223728910282690e-02, -4.688427928786876e-02, -3.285972322337551e-02, -2.070372815764913e-02, -1.189887570601912e-02, -5.066251784919897e-03, -1.075539101987261e-03, -6.012401647717178e-05, -5.849376198485588e-07]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


